package com.aistock.prediction.verification;
import java.time.*;import java.util.*;import com.aistock.common.BusinessException;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class RevisionAffectedMysqlTest {
 final VerificationMysqlTest d=new VerificationMysqlTest();VerificationDueRepository q(){return new VerificationDueRepository(d.f.jdbc,VerificationMysqlTest.MAPPER,VerificationMysqlTest.NOW,20);}
 @Test void completeHiddenForecastIsStillAffectedButOtherStockAndFutureAreNot(){var id=d.forecast("SUCCEEDED",true);var other=d.forecast("SUCCEEDED",false);d.f.jdbc.update("update forecast_request set instrument_id='SZ000002' where prediction_id=?",other.toString());d.forecast("FAILED",false);String vid=UUID.randomUUID().toString();d.f.jdbc.update("insert into forecast_verification_version(version_id,prediction_id,realization_version_id,rule_version,due_through,content_hash,evidence_json,evaluation_json,created_at) values(?,?,?,?,?,'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','{}','{\"verifiedCount\":5}',?)",vid,id.toString(),UUID.randomUUID().toString(),VerificationRecords.RULE,VerificationMysqlTest.TARGETS.get(0),java.sql.Timestamp.from(VerificationMysqlTest.NOW.instant()));d.f.jdbc.update("insert into forecast_verification_head(prediction_id,current_version_id,due_through) values(?,?,?)",id.toString(),vid,VerificationMysqlTest.TARGETS.get(0));var p=q().affected("SH600030",VerificationMysqlTest.TARGETS.get(1),null,50);assertEquals(List.of(id),p.items().stream().map(VerificationDueRepository.Item::predictionId).toList());assertTrue(q().affected("SH600030",VerificationMysqlTest.ORIGIN,null,50).items().isEmpty());assertThrows(BusinessException.class,()->q().affected("bad",VerificationMysqlTest.ORIGIN,null,50));}
 @Test void affectedKeysetAndCutoffValidation(){for(int i=0;i<3;i++)d.forecast("SUCCEEDED",false);var a=q().affected("SH600030",VerificationMysqlTest.TARGETS.get(1),null,2);var b=q().affected("SH600030",VerificationMysqlTest.TARGETS.get(1),a.nextCursor(),2);assertEquals(2,a.items().size());assertEquals(1,b.items().size());assertNull(b.nextCursor());assertThrows(BusinessException.class,()->q().affected("SH600030",LocalDate.parse("2027-01-01"),null,50));}
 @Test void completedCurrentCanBeReplacedByNewEvidenceWithoutChangingForecast(){var id=d.forecast("SUCCEEDED",true);var today=Clock.fixed(Instant.parse("2026-09-28T14:00:00Z"),ZoneOffset.UTC);var raw=new java.util.concurrent.atomic.AtomicReference<String>("102");var service=new VerificationService(new VerificationRepository(d.f.jdbc,VerificationMysqlTest.MAPPER,today),(r,p)->d.evidence(r.dueThrough(),UUID.randomUUID().toString(),raw.get()),new VerificationCalculator(),VerificationMysqlTest.MAPPER,today,20);var due=VerificationMysqlTest.TARGETS.get(4);var before=d.f.jdbc.queryForObject("select snapshot_json from forecast_request where prediction_id=?",String.class,id.toString());var a=service.verify(id,new VerificationRequest(UUID.randomUUID(),due,today.instant().plusSeconds(90)));assertEquals("AVAILABLE",a.state());assertEquals(5,service.current(id).path("result").path("verifiedCount").asInt());raw.set("103");var b=service.verify(id,new VerificationRequest(UUID.randomUUID(),due,today.instant().plusSeconds(90)));assertEquals("AVAILABLE",b.state());assertNotEquals(a.versionId(),b.versionId());assertEquals(b.versionId(),service.current(id).path("verificationVersionId").asText());assertEquals(2,d.f.jdbc.queryForObject("select count(*) from forecast_verification_version",Integer.class));assertEquals(before,d.f.jdbc.queryForObject("select snapshot_json from forecast_request where prediction_id=?",String.class,id.toString()));}
}
